"""Check the SC1 fixture score and generate the SC1 music21 oracle files.

    uv run --with music21==10.5.2 python -I tests/fixtures/generate-sc1.py
    uv run --with music21==10.5.2 python -I tests/fixtures/generate-sc1.py --renumber

sc1-open-score.sexp is hand-built in the canonical form of src/sexp.lisp; its
ids must be the ones MAKE-SCORE mints for an id-less copy, checked (or, with
--renumber, rewritten) by generate-sc0.py's independent minting walk.

Then music21 computes, from the fixture scores:
  sc1-transposed.sexp  (fixture op pitches keys anchors): every note and chord
                       note after Score.transpose, in document order; the keys
                       of the measures that have one; chord-symbol roots and
                       basses. A TO-KEY row moves the score by the interval
                       listed with it, the one music-theory's TRANSPOSE-TO-KEY
                       takes between the two tonics (the suite checks that).
  sc1-unfolded.sexp    (:cases (name source spec order) :fixtures (fixture
                       source-measure-ids notes)): Part.expandRepeats on
                       one-note navigation scores and on the fixtures with
                       repeats and jumps. Cases where music21 doesn't follow our
                       conventions (PROVENANCE.md) are listed with source
                       :rules and the order our rules give, worked out by hand.
  sc1-parts.sexp       (fixture id notes): the sounding notes of a part or one
                       voice. NOTES are (onset pitch...) sorted by onset, then
                       by the pitch text.
Offsets are in whole notes (music21 quarterLength / 4).
"""

import importlib.util
import os
import sys
from fractions import Fraction

HERE = os.path.dirname(os.path.abspath(__file__))
_spec = importlib.util.spec_from_file_location("sc0", os.path.join(HERE, "generate-sc0.py"))
sc0 = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(sc0)
parse, plist, items, lisp = sc0.parse, sc0.plist, sc0.items, sc0.lisp
m21_pitch = sc0.m21_pitch


def load(name):
    with open(os.path.join(HERE, name + ".sexp"), encoding="utf-8") as f:
        return parse(f.read())


def write(name, header, body):
    with open(os.path.join(HERE, name), "w", encoding="utf-8") as out:
        out.write(f";;;; {header}\n;;;; Generated by generate-sc1.py with music21 10.5.2. Do not edit.\n")
        out.write(body)


def rows_text(rows):
    return "(\n" + "".join(" " + lisp(r) + "\n" for r in rows) + ")\n"


def our_name(m21_name):
    """music21 'B-4' → our 'Bb4'."""
    return m21_name.replace("-", "b")


QUALITY_KINDS = {"major": "major", "minor": "minor", "dominant-7": "dominant-seventh",
                 "minor-7": "minor-seventh"}

JUMPS = {"segno": "Segno", "coda": "Coda", "fine": "Fine", "da-capo": "DaCapo",
         "da-capo-al-fine": "DaCapoAlFine", "da-capo-al-coda": "DaCapoAlCoda",
         "dal-segno": "DalSegno", "dal-segno-al-fine": "DalSegnoAlFine",
         "dal-segno-al-coda": "DalSegnoAlCoda"}


def build(score_node, chord_symbols=False, navigation=False):
    """A music21 Score of a fixture: parts, measures, voices. Returns the score,
    the first part's measures, and id → music21 object for notes, chord notes
    (the chord's note in that position) and anchors."""
    from music21 import stream, note, chord, meter, key, harmony, bar, repeat, spanner
    _, s = plist(score_node)
    measures = items(s.get("measures"))
    first_bar = 0 if plist(measures[0])[1].get("pickup") else 1
    sc = stream.Score()
    objects = {}
    first_part_measures = None
    for part in items(s.get("parts")):
        p_m21 = stream.Part()
        _, p = plist(part)
        voices = items(p.get("voices"))
        bars = []
        for i, mnode in enumerate(measures):
            _, mk = plist(mnode)
            m = stream.Measure(number=first_bar + i)
            m.id = mk["id"].value
            if "time" in mk:
                m.insert(0, meter.TimeSignature(mk["time"].value))
            if "key" in mk:
                tonic, mode = mk["key"].value.split(" ")
                k = key.Key(m21_pitch(tonic + "4")[:-1], mode)
                m.insert(0, k)
                objects[mk["id"].value + "/key"] = k
            if navigation:
                if mk.get("repeat-start"):
                    m.leftBarline = bar.Repeat(direction="start")
                if mk.get("repeat-end"):
                    m.rightBarline = bar.Repeat(direction="end", times=int(mk["repeat-end"].value))
            for vi, voice in enumerate(voices):
                _, vk = plist(voice)
                v = stream.Voice(id=str(vi + 1))
                for event in items(items(vk.get("measures"))[i]):
                    kind, e = plist(event)
                    ql = Fraction(e["duration"].value) * 4
                    if kind == "rest":
                        obj = note.Rest(quarterLength=ql)
                    elif kind == "note":
                        obj = note.Note(m21_pitch(e["pitch"].value), quarterLength=ql)
                    else:
                        obj = chord.Chord([m21_pitch(plist(n)[1]["pitch"].value)
                                           for n in items(e["notes"])], quarterLength=ql)
                    if "grace" in e:
                        obj = obj.getGrace()
                    v.append(obj)
                    objects[e["id"].value] = obj
                    if kind == "chord":
                        for ni, n in enumerate(items(e["notes"])):
                            objects[plist(n)[1]["id"].value] = (obj, ni)
                m.insert(0, v)
            if navigation:
                for j in items(mk.get("jump")):
                    kind = plist(j)[1]["kind"].value
                    if kind == "to-coda":
                        m.insert(m.highestTime, repeat.Coda("To Coda"))
                    else:
                        obj = getattr(repeat, JUMPS[kind])()
                        m.insert(0 if kind in ("segno", "coda") else m.highestTime, obj)
            bars.append(m)
        for i, m in enumerate(bars):
            _, mk = plist(measures[i])
            if i == 0 and mk.get("pickup"):
                m.paddingLeft = m.timeSignature.barDuration.quarterLength - m.highestTime
            p_m21.append(m)
        if navigation:
            for i, mnode in enumerate(measures):
                ending = plist(mnode)[1].get("ending")
                if ending is not None:
                    _, ek = plist(ending)
                    passes = [int(x.value) for x in items(ek["passes"])]
                    count = int(ek["measures"].value) if "measures" in ek else 1
                    p_m21.insert(0, spanner.RepeatBracket(bars[i:i + count],
                                                          number=",".join(map(str, passes))))
        sc.insert(0, p_m21)
        if first_part_measures is None:
            first_part_measures = bars
    if chord_symbols:
        for a in items(s.get("chord-symbols")):
            _, ak = plist(a)
            bar_index, offset = int(ak["bar"].value) - first_bar, Fraction(ak["offset"].value)
            values = ak["symbol"].value
            sym = {values[i].value: values[i + 1] for i in range(0, len(values), 2)}
            if sym.get("no-chord-p"):
                obj = harmony.NoChord()
            else:
                args = {"root": m21_pitch(sym["root"].value + "4")[:-1],
                        "kind": QUALITY_KINDS.get(sym["quality"].value, "major")}
                if "bass" in sym:
                    args["bass"] = m21_pitch(sym["bass"].value + "4")[:-1]
                obj = harmony.ChordSymbol(**args)
            first_part_measures[bar_index].insert(offset * 4, obj)
            objects[ak["id"].value] = (obj, "bass" in sym)
    return sc, first_part_measures, objects, first_bar


# --- transposition ----------------------------------------------------------

TRANSPOSE_ROWS = [
    ("sc0-satb", "M2"), ("sc0-chords-under-rests", "m2"), ("sc0-chords-under-rests", "-m3"),
    ("sc0-key-change", "P4"), ("sc0-carol-6-8", "-M2"), ("sc0-keyboard", "P5"),
    ("sc0-pickup", "m2"), ("sc0-repeats-voltas", "-P4"), ("sc0-jumps", "M3"),
    ("sc0-three-verses", "d1"), ("sc0-three-verses", "m2"), ("sc0-omr-result", "P8"),
    ("sc1-open-score", "-M2"),
    # TO-KEY rows: music21 moves the score by the interval music-theory's
    # TRANSPOSE-TO-KEY takes between the tonics (data here, not a rule).
    ("sc0-chords-under-rests", ("to-key", "Eb major", "-M2")),
    ("sc0-satb", ("to-key", "E major", "-m3")),
    ("sc0-jumps", ("to-key", "D minor", "-M2")),
    ("sc0-key-change", ("to-key", "Db major", "m2"))]


def transposed_row(name, spec):
    from music21 import interval, harmony
    node = load(name)
    sc, bars, objects, _ = build(node, chord_symbols=True)
    _, s = plist(node)
    if isinstance(spec, tuple):
        iv = interval.Interval(spec[2])
        form = [":transpose", ":to-key", spec[1]]
    else:
        iv = interval.Interval(spec)
        form = [":transpose", ":interval", spec]
    sc.transpose(iv, inPlace=True)
    pitches, keys, anchors = [], [], []
    for element in sc0.document_order(node):
        kind, k = plist(element)
        ident = k["id"].value if "id" in k else None
        if kind in ("note", "chord-note"):
            obj = objects[ident]
            if isinstance(obj, tuple):
                chord_obj, index = obj
                pitch_name = chord_obj.notes[index].nameWithOctave
            else:
                pitch_name = obj.nameWithOctave
            pitches.append([ident, our_name(pitch_name)])
        elif kind == "measure" and "key" in k:
            kobj = objects[ident + "/key"]
            keys.append([ident, our_name(kobj.tonic.name) + " " + kobj.mode])
        elif kind == "chord-symbol":
            obj, has_bass = objects[ident]
            if isinstance(obj, harmony.NoChord):
                anchors.append([ident, None, None])
            else:
                anchors.append([ident, our_name(obj.root().name),
                                our_name(obj.bass().name) if has_bass else None])
    return [name, Sym(form), pitches, keys, anchors]


class Sym:
    """A form printed with keywords unquoted: (:transpose :interval "M2")."""

    def __init__(self, items_):
        self.items = items_


_lisp = sc0.lisp


def lisp_out(value):
    if isinstance(value, Sym):
        return "(" + " ".join(v if v.startswith(":") else _lisp(v) for v in value.items) + ")"
    if isinstance(value, (list, tuple)):
        return "(" + " ".join(lisp_out(v) for v in value) + ")"
    return _lisp(value)


# --- unfolding ----------------------------------------------------------------

def nav_part(spec):
    """A one-note-per-measure music21 Part for a navigation SPEC (see the Lisp
    NAV-SCORE): measure i holds the note whose lyric is i."""
    from music21 import stream, note, meter, bar, repeat, spanner
    p = stream.Part()
    ms = []
    for i, d in enumerate(spec):
        m = stream.Measure(number=i)
        if i == 0:
            m.insert(0, meter.TimeSignature("1/4"))
        n = note.Note("C4", quarterLength=1)
        n.lyric = str(i)
        m.append(n)
        if d.get("repeat-start"):
            m.leftBarline = bar.Repeat(direction="start")
        if d.get("repeat-end"):
            m.rightBarline = bar.Repeat(direction="end", times=d["repeat-end"])
        for j in d.get("jump", []):
            if j == "to-coda":
                m.insert(1, repeat.Coda("To Coda"))
            else:
                m.insert(0 if j in ("segno", "coda") else 1, getattr(repeat, JUMPS[j])())
        ms.append(m)
        p.append(m)
    for i, d in enumerate(spec):
        if d.get("ending"):
            passes, count = d["ending"]
            p.insert(0, spanner.RepeatBracket(ms[i:i + count], number=",".join(map(str, passes))))
    return p


def spec_form(spec):
    out = []
    for d in spec:
        items_ = []
        if d.get("repeat-start"):
            items_ += [":repeat-start", "t"]
        if d.get("repeat-end"):
            items_ += [":repeat-end", str(d["repeat-end"])]
        if d.get("ending"):
            passes, count = d["ending"]
            items_ += [":ending", "((" + " ".join(map(str, passes)) + ") " + str(count) + ")"]
        if d.get("jump"):
            items_ += [":jump", "(" + " ".join(":" + j for j in d["jump"]) + ")"]
        out.append("(" + " ".join(items_) + ")")
    return "(" + " ".join(out) + ")"


R, E = "repeat-start", "repeat-end"
NAV_CASES = [
    ("voltas", [{R: 1}, {}, {"ending": ((1,), 2)}, {E: 2}, {"ending": ((2,), 1)},
                {R: 1}, {E: 3, "ending": ((1, 2), 1)}, {"ending": ((3,), 1)}], None),
    ("voltas, one-bar endings", [{R: 1}, {}, {"ending": ((1,), 1), E: 2}, {"ending": ((2,), 1)},
                                 {}, {}], None),
    ("played three times", [{R: 1}, {E: 3}], None),
    ("a repeat sign at both ends", [{R: 1, E: 2}, {}], None),
    ("a backward repeat to the beginning", [{}, {}, {E: 2}, {}], None),
    ("D.S. al Coda", [{}, {"jump": ["segno"]}, {}, {"jump": ["to-coda"]},
                      {"jump": ["dal-segno-al-coda"]}, {"jump": ["coda"]}, {}], None),
    ("D.C. al Fine", [{}, {"jump": ["fine"]}, {}, {"jump": ["da-capo-al-fine"]}], None),
    ("D.C.", [{}, {}, {"jump": ["da-capo"]}], None),
    ("D.C. al Coda", [{}, {"jump": ["to-coda"]}, {}, {"jump": ["da-capo-al-coda"]},
                      {"jump": ["coda"]}, {}], None),
    ("D.S. al Fine", [{}, {"jump": ["segno"]}, {"jump": ["fine"]}, {}, {"jump": ["dal-segno-al-fine"]}],
     None),
    ("no repeats after D.C.", [{R: 1}, {E: 2, "jump": ["fine"]}, {}, {"jump": ["da-capo-al-fine"]}], None),
    ("two sections, then D.C.", [{R: 1}, {E: 2}, {R: 1}, {E: 2}, {"jump": ["da-capo"]}], None),
    # music21 differs on these (PROVENANCE.md): the rules' orders.
    ("a second section without a forward repeat", [{}, {}, {E: 2}, {}, {E: 2}, {}],
     [0, 1, 2, 0, 1, 2, 3, 4, 3, 4, 5]),
    ("voltas, then D.C. al Fine", [{R: 1}, {}, {"ending": ((1,), 1), E: 2}, {"ending": ((2,), 1)},
                                   {"jump": ["fine"]}, {}, {"jump": ["da-capo-al-fine"]}],
     [0, 1, 2, 0, 1, 3, 4, 5, 6, 0, 1, 3, 4]),
    ("voltas inside a D.S.", [{}, {R: 1, "jump": ["segno"]}, {"ending": ((1,), 1), E: 2},
                              {"ending": ((2,), 1)}, {}, {"jump": ["dal-segno"]}],
     [0, 1, 2, 1, 3, 4, 5, 1, 3, 4, 5]),
    ("voltas, then D.C.", [{R: 1}, {}, {"ending": ((1,), 1), E: 2}, {"ending": ((2,), 1)}, {},
                           {"jump": ["da-capo"]}],
     [0, 1, 2, 0, 1, 3, 4, 5, 0, 1, 3, 4, 5]),
]


def nav_rows():
    from music21 import stream
    rows = []
    for name, spec, rules in NAV_CASES:
        if rules is None:
            expanded = nav_part(spec).expandRepeats()
            order = [int(m.notes[0].lyric) for m in expanded.getElementsByClass(stream.Measure)]
            source = ":music21"
        else:
            order = rules
            source = ":rules"
        rows.append("(" + lisp(name) + " " + source + " " + spec_form(spec) + " " + lisp(order) + ")")
    return rows


def unfold_fixture_row(name):
    from music21 import stream, note, chord
    node = load(name)
    sc, _, _, first_bar = build(node, navigation=True)
    _, s = plist(node)
    ids = [plist(m)[1]["id"].value for m in items(s["measures"])]
    parts = list(sc.parts)
    expanded = [p.expandRepeats() for p in parts]
    sources = [m.id for m in expanded[0].getElementsByClass(stream.Measure)]
    if any(source not in ids for source in sources):
        raise ValueError(f"{name}: expanded measures lost their ids: {sources}")
    notes = []
    for p in expanded:
        for el in p.flatten().notes:
            if el.duration.isGrace:
                continue
            onset = Fraction(el.getOffsetInHierarchy(p)) / 4
            names = ([our_name(x.nameWithOctave) for x in el.notes] if isinstance(el, chord.Chord)
                     else [our_name(el.nameWithOctave)])
            notes.append([onset] + names)
    notes.sort(key=lambda r: (r[0], " ".join(r[1:])))
    return [name, sources, notes]


# --- parts ------------------------------------------------------------------

PART_ROWS = [("sc0-keyboard", "p-5"), ("sc0-keyboard", "p-o"), ("sc0-satb", "p-5"),
             ("sc0-satb", "v-s"), ("sc0-satb", "v-13"), ("sc0-three-verses", "p-5"),
             ("sc1-open-score", None)]


def part_rows():
    from music21 import stream, chord
    rows = []
    for name, ident in PART_ROWS:
        node = load(name)
        sc, _, _, _ = build(node)
        _, s = plist(node)
        parts = items(s["parts"])
        targets = []
        if ident is None:
            targets = [(plist(p)[1]["id"].value, i, None) for i, p in enumerate(parts)]
        else:
            for i, p in enumerate(parts):
                _, pk = plist(p)
                if pk["id"].value == ident:
                    targets.append((ident, i, None))
                for vi, v in enumerate(items(pk["voices"])):
                    if plist(v)[1]["id"].value == ident:
                        targets.append((ident, i, str(vi + 1)))
        for tid, pi, voice in targets:
            part = sc.parts[pi]
            notes = []
            if voice is None:
                found = [(el, Fraction(el.getOffsetInHierarchy(sc))) for el in part.flatten().notes]
            else:
                found = [(el, Fraction(m.getOffsetInHierarchy(sc)) + Fraction(el.offset))
                         for m in part.getElementsByClass(stream.Measure)
                         for v in m.voices if v.id == voice
                         for el in v.notes]
            for el, ql in found:
                if el.duration.isGrace:
                    continue
                onset = ql / 4
                names = ([our_name(x.nameWithOctave) for x in el.notes] if isinstance(el, chord.Chord)
                         else [our_name(el.nameWithOctave)])
                notes.append([onset] + names)
            notes.sort(key=lambda r: (r[0], " ".join(r[1:])))
            rows.append([name, tid, notes])
    return rows


def main():
    renumber = "--renumber" in sys.argv
    path = os.path.join(HERE, "sc1-open-score.sexp")
    with open(path, encoding="utf-8") as f:
        text = f.read()
    canonical, _ = sc0.renumbered(text)
    if canonical != text:
        if not renumber:
            sys.exit("sc1-open-score.sexp: ids are not in document order (run with --renumber)")
        with open(path, "w", encoding="utf-8") as f:
            f.write(canonical)
    transposed = [transposed_row(n, spec) for n, spec in TRANSPOSE_ROWS]
    write("sc1-transposed.sexp",
          "SC1 transposition: (fixture op ((id pitch)...) ((measure key)...) ((anchor root bass)...))",
          "(\n" + "".join(" " + lisp_out(r) + "\n" for r in transposed) + ")\n")
    cases = nav_rows()
    fixtures = [unfold_fixture_row(n) for n in ("sc0-repeats-voltas", "sc0-jumps")]
    write("sc1-unfolded.sexp",
          "SC1 unfolding: :cases (name source spec order), :fixtures (fixture measures notes)",
          "(:cases\n (" + "\n  ".join(cases) + ")\n :fixtures\n " + rows_text(fixtures) + ")\n")
    write("sc1-parts.sexp", "SC1 parts: (fixture id ((onset pitch...)...))", rows_text(part_rows()))
    print(f"{len(transposed)} transpositions, {len(cases)} navigation cases, "
          f"{len(fixtures)} unfolded fixtures")


if __name__ == "__main__":
    main()
